import { QueryCommand, ScanCommand } from "@aws-sdk/lib-dynamodb";
import { ddb } from "../utils/dynamo";
import { ProductRepository } from "../repo/product.repo";
import { getActiveDiscounts } from "./discount.service";
import { applyDiscount } from "./price.service";

const PRODUCT_TABLE = process.env.PRODUCTS_TABLE!;
export async function getActiveProducts(
    limit: number,
    lastKey?: any,
    search?: string
) {
    const searchLower = search?.toLowerCase();
    if (searchLower) {
        const params: any = {
            TableName: PRODUCT_TABLE,
            FilterExpression: "isActive = :true AND contains(#st, :q) AND #qty >= :minQty",
            ExpressionAttributeNames: {
                "#st": "searchText",
                "#qty": "quantity",
            },
            ExpressionAttributeValues: {
                ":true": "true",
                ":q": searchLower,
                ":minQty": 1,
            },
        };

        const res = await ddb.send(new ScanCommand(params));
        return {
            items: (res.Items || []).slice(0, limit),
            lastKey: res.LastEvaluatedKey,
        };
    }

    const params: any = {
        TableName: PRODUCT_TABLE,
        IndexName: "isActive-index",
        KeyConditionExpression: "isActive = :true",
        ExpressionAttributeValues: {
            ":true": "true",
        },
        Limit: limit,
        ExclusiveStartKey: lastKey,
    };

    const res = await ddb.send(new QueryCommand(params));
    return {
        items: res.Items || [],
        lastKey: res.LastEvaluatedKey,
    };
}

export async function getAllActiveProducts() {
    const items: any[] = [];
    let lastKey: any = undefined;

    do {
        const res = await ddb.send(
            new QueryCommand({
                TableName: PRODUCT_TABLE,
                IndexName: "isActive-index",
                KeyConditionExpression: "isActive = :true",
                ExpressionAttributeValues: {
                    ":true": "true",
                },
                ExclusiveStartKey: lastKey,
            })
        );

        items.push(...(res.Items || []));
        lastKey = res.LastEvaluatedKey;
    } while (lastKey);

    return items.filter((p) => Number(p.quantity) > 0);
}

export class ProductService {
    constructor(private repo = new ProductRepository()) { }

    async batchGetProducts(productIds: string[]) {
        const uniqueIds = [...new Set(productIds)];
        const allProducts: any[] = [];

        for (let i = 0; i < uniqueIds.length; i += 100) {
            const chunk = uniqueIds.slice(i, i + 100);
            const products = await this.repo.batchGet(chunk);
            if (products?.length) {
                allProducts.push(...products);
            }
        }

        if (allProducts.length === 0) return [];
        const discounts = await getActiveDiscounts();
        const productMap = new Map(
            allProducts.map((p) => [p.productId, p])
        );

        return uniqueIds
            .map((id) => productMap.get(id))
            .filter((p): p is any => Boolean(p))
            .filter((p) => p.isActive === "true" || p.isActive === true)
            .map((p) => {
                const priceInfo = applyDiscount(p, discounts);
                return {
                    productId: p.productId,
                    name: p.name,
                    description: p.description ?? null,
                    image: p.imageUrls?.[0] ?? null,
                    price: priceInfo.price,
                    originalPrice: priceInfo.originalPrice > priceInfo.price ? priceInfo.originalPrice : undefined,
                    discountText: priceInfo.discountText,
                    categoryId: p.categoryId,
                    brandId: p.brandId,
                    qty: p.quantity,
                    searchText: p.searchText,
                    isComboPackage: p.isComboPackage || false,
                    sequenceNumber: p.sequenceNumber || 0,
                    cartonQty: p.cartonQty || 0,
                    bulkOrderBasePrice: p.bulkOrderBasePrice || 0,
                    isBulkOrderOnly: p.isBulkOrderOnly || false,
                    isRetailOnly: p.isRetailOnly || false,
                    productPer: p.productPer || 0,
                    productMeasurement: p.productMeasurement || "",
                };
            });
    }

    async deleteProduct(productId: string) {
        return this.repo.deleteProduct(productId);
    }
}